"""Tests for the lock file check.

The real check runs uv, which needs network access. These tests replace the
uv call with a function that writes a known lock file, so they test only the
comparison logic.
"""

from __future__ import annotations

from pathlib import Path

from lock_files import LockFile, check_locks, compare_locks, main, parse_lock

LOCK = """\
# This file was autogenerated by uv via the following command:
#    python scripts/lock_files.py update
arcgis==2.4.4 \\
    --hash=sha256:aaa \\
    --hash=sha256:bbb
    # via -r requirements.txt
pywin32==312 ; sys_platform == 'win32' \\
    --hash=sha256:ccc
    # via arcgis
requests==2.32.3 \\
    --hash=sha256:ddd
    # via arcgis
"""


# --- Parsing a lock file ------------------------------------------------------


def test_parse_lock_reads_versions_markers_and_hashes():
    entries = parse_lock(LOCK)
    assert entries == {
        ("arcgis", ""): ("2.4.4", frozenset({"sha256:aaa", "sha256:bbb"})),
        ("pywin32", "sys_platform == 'win32'"): ("312", frozenset({"sha256:ccc"})),
        ("requests", ""): ("2.32.3", frozenset({"sha256:ddd"})),
    }


def test_parse_lock_normalizes_package_names():
    entries = parse_lock("PyYAML==6.0.3 \\\n    --hash=sha256:x\n")
    assert ("pyyaml", "") in entries


# --- Comparing locks --------------------------------------------------------


def test_identical_locks_have_no_problems():
    assert compare_locks(LOCK, LOCK) == []


def test_comments_and_header_do_not_matter():
    other_header = LOCK.replace("python scripts/lock_files.py update", "something else")
    assert compare_locks(LOCK, other_header) == []


def test_package_added_directly_to_lock_is_reported():
    tampered = LOCK + "evil-package==1.0 \\\n    --hash=sha256:eee\n"
    problems = compare_locks(committed=tampered, expected=LOCK)
    assert problems == [
        "Lukitustiedostossa on paketti, jota requirements-tiedosto ei vaadi: "
        "evil-package==1.0"
    ]


def test_missing_package_is_reported():
    without_requests = LOCK.split("requests==")[0]
    problems = compare_locks(committed=without_requests, expected=LOCK)
    assert problems == ["Lukitustiedostosta puuttuu paketti: requests==2.32.3"]


def test_changed_version_is_reported():
    old = LOCK.replace("arcgis==2.4.4", "arcgis==2.4.3")
    problems = compare_locks(committed=old, expected=LOCK)
    assert problems == [
        "Lukitustiedoston versio ei vastaa requirements-tiedostoa: "
        "arcgis on 2.4.3, pitäisi olla 2.4.4"
    ]


def test_changed_hash_is_reported():
    tampered = LOCK.replace("sha256:ddd", "sha256:fff")
    problems = compare_locks(committed=tampered, expected=LOCK)
    assert problems == ["Lukitustiedoston hash ei vastaa pakettirekisteriä: requests==2.32.3"]


def test_platform_marker_is_shown_in_messages():
    without_pywin32 = LOCK.replace(
        "pywin32==312 ; sys_platform == 'win32' \\\n    --hash=sha256:ccc\n    # via arcgis\n", ""
    )
    problems = compare_locks(committed=without_pywin32, expected=LOCK)
    assert problems == [
        "Lukitustiedostosta puuttuu paketti: pywin32==312 ; sys_platform == 'win32'"
    ]


# --- check_locks() with a fake uv -------------------------------------------


def fake_compile(content: str):
    """Return a compile function that 'generates' the given lock content."""

    def compile_lock(source: Path, output: Path) -> None:
        output.write_text(content, encoding="utf-8")

    return compile_lock


def test_check_passes_when_lock_matches(tmp_path):
    (tmp_path / "requirements.lock.txt").write_text(LOCK, encoding="utf-8")
    locks = [LockFile("requirements.txt", "requirements.lock.txt")]
    assert check_locks(locks, tmp_path, fake_compile(LOCK)) == []


def test_check_gives_uv_the_existing_versions_without_hashes(tmp_path):
    # uv keeps the versions already in the output file. The check must give it
    # the committed versions, or every new release on PyPI would make the check
    # fail. But uv also keeps the *hashes* it finds there, so a tampered hash
    # would survive. Giving uv only the versions makes it fetch real hashes.
    (tmp_path / "requirements.lock.txt").write_text(LOCK, encoding="utf-8")
    seen = {}

    def compile_lock(source: Path, output: Path) -> None:
        seen["content"] = output.read_text(encoding="utf-8")
        output.write_text(LOCK, encoding="utf-8")

    check_locks([LockFile("requirements.txt", "requirements.lock.txt")], tmp_path, compile_lock)
    assert "--hash" not in seen["content"]
    assert seen["content"].splitlines() == [
        "arcgis==2.4.4",
        "pywin32==312 ; sys_platform == 'win32'",
        "requests==2.32.3",
    ]


def test_check_detects_tampered_hash(tmp_path):
    tampered = LOCK.replace("sha256:ddd", "sha256:000")
    (tmp_path / "requirements.lock.txt").write_text(tampered, encoding="utf-8")
    locks = [LockFile("requirements.txt", "requirements.lock.txt")]
    problems = check_locks(locks, tmp_path, fake_compile(LOCK))
    assert problems == [
        "requirements.lock.txt: Lukitustiedoston hash ei vastaa pakettirekisteriä: "
        "requests==2.32.3"
    ]


def test_check_reports_problems_with_file_name(tmp_path):
    tampered = LOCK + "evil-package==1.0 \\\n    --hash=sha256:eee\n"
    (tmp_path / "requirements.lock.txt").write_text(tampered, encoding="utf-8")
    locks = [LockFile("requirements.txt", "requirements.lock.txt")]
    problems = check_locks(locks, tmp_path, fake_compile(LOCK))
    assert problems == [
        "requirements.lock.txt: Lukitustiedostossa on paketti, jota "
        "requirements-tiedosto ei vaadi: evil-package==1.0"
    ]


def test_check_reports_missing_lock_file(tmp_path):
    locks = [LockFile("requirements.txt", "requirements.lock.txt")]
    problems = check_locks(locks, tmp_path, fake_compile(LOCK))
    assert problems == ["requirements.lock.txt puuttuu"]


# --- main() ---------------------------------------------------------------


def test_main_check_prints_result_and_uses_exit_code(tmp_path, monkeypatch, capsys):
    monkeypatch.chdir(tmp_path)
    exit_code = main(["check"], locks=[LockFile("requirements.txt", "requirements.lock.txt")],
                     compile_lock=fake_compile(LOCK))
    output = capsys.readouterr().out
    assert exit_code == 1
    assert "TULOS: HYLATTY" in output
    assert "SYY: requirements.lock.txt puuttuu" in output
    assert "python scripts/lock_files.py update" in output


def test_main_check_azure_devops(tmp_path, monkeypatch, capsys):
    monkeypatch.chdir(tmp_path)
    exit_code = main(["check", "--azure-devops"],
                     locks=[LockFile("requirements.txt", "requirements.lock.txt")],
                     compile_lock=fake_compile(LOCK))
    vso = [l for l in capsys.readouterr().out.splitlines() if l.startswith("##vso[")]
    assert exit_code == 0
    assert vso[0] == "##vso[task.logissue type=error]requirements.lock.txt puuttuu"
    assert vso[-1].startswith("##vso[task.complete result=Failed;]")


def test_main_check_passes(tmp_path, monkeypatch, capsys):
    (tmp_path / "requirements.lock.txt").write_text(LOCK, encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    exit_code = main(["check"], locks=[LockFile("requirements.txt", "requirements.lock.txt")],
                     compile_lock=fake_compile(LOCK))
    assert exit_code == 0
    assert "TULOS: HYVAKSYTTY" in capsys.readouterr().out
